import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { immediateTransaction } from './db.ts';
import type { Submission } from './validation.ts';

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** The JSON shape returned by every endpoint that returns a job. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

interface JobRow {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  created_at: string;
  updated_at: string;
}

const JOB_COLUMNS =
  'id, status, input, steps, fail_attempts, attempts, progress_completed, result_output, error, created_at, updated_at';

export function toJob(row: JobRow): Job {
  return {
    id: row.id,
    status: row.status,
    input: row.input,
    steps: row.steps,
    failAttempts: row.fail_attempts,
    attempts: row.attempts,
    progress: { completed: row.progress_completed, total: row.steps },
    result: row.status === 'completed' && row.result_output !== null ? { output: row.result_output } : null,
    error: row.status === 'failed' ? row.error : null,
    createdAt: row.created_at,
    updatedAt: row.updated_at,
  };
}

export function getJob(db: DatabaseSync, id: string): Job | undefined {
  const row = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs WHERE id = ?`).get(id) as JobRow | undefined;
  return row ? toJob(row) : undefined;
}

/** All jobs, newest first. */
export function listJobs(db: DatabaseSync): Job[] {
  const rows = db.prepare(`SELECT ${JOB_COLUMNS} FROM jobs ORDER BY seq DESC`).all() as unknown as JobRow[];
  return rows.map(toJob);
}

export type SubmitResult =
  | { kind: 'created'; job: Job }
  | { kind: 'replayed'; job: Job }
  | { kind: 'conflict' };

/**
 * Creates a job, or resolves an idempotent replay. The key lookup and insert happen in one write
 * transaction so a key can never create two jobs.
 */
export function submitJob(db: DatabaseSync, payload: Submission, idempotencyKey: string | undefined): SubmitResult {
  const fingerprint = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);
  return immediateTransaction(db, (): SubmitResult => {
    if (idempotencyKey !== undefined) {
      const existing = db
        .prepare('SELECT fingerprint, job_id FROM idempotency_keys WHERE key = ?')
        .get(idempotencyKey) as { fingerprint: string; job_id: string } | undefined;
      if (existing) {
        if (existing.fingerprint !== fingerprint) return { kind: 'conflict' };
        const job = getJob(db, existing.job_id);
        if (!job) throw new Error(`idempotency key ${idempotencyKey} refers to missing job ${existing.job_id}`);
        return { kind: 'replayed', job };
      }
    }

    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, available_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, 0, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, now, now);
    if (idempotencyKey !== undefined) {
      db.prepare('INSERT INTO idempotency_keys (key, fingerprint, job_id) VALUES (?, ?, ?)').run(idempotencyKey, fingerprint, id);
    }
    const job = getJob(db, id);
    if (!job) throw new Error(`inserted job ${id} could not be read back`);
    return { kind: 'created', job };
  });
}

