/** Validation for `POST /api/jobs`. Every rule from TASK.md is enforced here. */

export interface Submission {
  input: string;
  steps: number;
  failAttempts: number;
}

export interface FieldError {
  field: string;
  message: string;
}

export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;
const ALLOWED_FIELDS = new Set(['input', 'steps', 'failAttempts']);
const DEFAULT_STEPS = 5;
const DEFAULT_FAIL_ATTEMPTS = 0;

export type ParseResult = { ok: true; value: Submission } | { ok: false; fields: FieldError[] };

/** Checks the `Idempotency-Key` header value. Returns an error entry, or undefined when valid or absent. */
export function checkIdempotencyKey(raw: string | string[] | undefined): FieldError | undefined {
  if (raw === undefined) return undefined;
  if (typeof raw === 'string' && IDEMPOTENCY_KEY_PATTERN.test(raw)) return undefined;
  return { field: 'Idempotency-Key', message: 'must be 1-128 characters of letters, digits, "_" or "-"' };
}

/** True when the Content-Type header names application/json (parameters such as charset are allowed). */
export function isJsonContentType(raw: string | undefined): boolean {
  if (raw === undefined) return false;
  return raw.split(';')[0]!.trim().toLowerCase() === 'application/json';
}

/** Parses a raw request body (already checked for Content-Type) and validates it. */
export function parseSubmissionBody(rawBody: string): ParseResult {
  let parsed: unknown;
  try {
    parsed = JSON.parse(rawBody);
  } catch {
    return { ok: false, fields: [{ field: 'body', message: 'must be valid JSON' }] };
  }
  return validateSubmission(parsed);
}

export function validateSubmission(value: unknown): ParseResult {
  if (typeof value !== 'object' || value === null || Array.isArray(value)) {
    return { ok: false, fields: [{ field: 'body', message: 'must be a JSON object' }] };
  }
  const obj = value as Record<string, unknown>;
  const fields: FieldError[] = [];

  for (const key of Object.keys(obj)) {
    if (!ALLOWED_FIELDS.has(key)) fields.push({ field: key, message: 'is not a recognised field' });
  }

  let input = '';
  const rawInput = obj.input;
  if (rawInput === undefined) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof rawInput !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (rawInput.length < 1 || rawInput.length > 1000) {
    fields.push({ field: 'input', message: 'must be 1-1000 characters' });
  } else if (rawInput.trim() === '') {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = rawInput;
  }

  const steps = integerField(obj, 'steps', DEFAULT_STEPS, 1, 20, fields);
  const failAttempts = integerField(obj, 'failAttempts', DEFAULT_FAIL_ATTEMPTS, 0, 5, fields);

  if (fields.length > 0) return { ok: false, fields };
  return { ok: true, value: { input, steps, failAttempts } };
}

function integerField(
  obj: Record<string, unknown>,
  name: string,
  fallback: number,
  min: number,
  max: number,
  fields: FieldError[],
): number {
  const raw = obj[name];
  if (raw === undefined) return fallback;
  if (typeof raw !== 'number' || !Number.isInteger(raw)) {
    fields.push({ field: name, message: 'must be an integer' });
    return fallback;
  }
  if (raw < min || raw > max) {
    fields.push({ field: name, message: `must be between ${min} and ${max}` });
    return fallback;
  }
  return raw;
}

