65	      formError.append(p);
66	      if (fields && fields.length > 0) {
67	        const ul = document.createElement('ul');
68	        for (const f of fields) {
69	          const li = document.createElement('li');
70	          li.textContent = `${f.field}: ${f.message}`;
71	          ul.append(li);
72	        }
73	        formError.append(ul);
74	      }
75	    }
76	
77	    function buildItem(job) {
78	      const li = document.createElement('li');
79	      li.setAttribute('data-testid', 'job-item');
80	      li.setAttribute('data-job-id', job.id);
81	
82	      const input = document.createElement('div');
83	      input.className = 'job-input';
84	      input.textContent = job.input;
85	
86	      const meta = document.createElement('div');
87	      meta.className = 'job-meta';
88	      const status = document.createElement('span');
89	      status.setAttribute('data-testid', 'job-status');
90	      status.textContent = job.status;
91	      const progress = document.createElement('span');
92	      progress.setAttribute('data-testid', 'job-progress');
93	      progress.textContent = `${job.progress.completed}/${job.progress.total}`;
94	      meta.append(status, progress);
95	
96	      const result = document.createElement('div');
97	      result.setAttribute('data-testid', 'job-result');
98	      if (job.status === 'completed') result.textContent = job.result ? job.result.output : '';
99	      else if (job.status === 'failed') result.textContent = job.error ?? '';
100	      else result.textContent = '';
101	
102	      li.append(input, meta, result);
103	      return li;
104	    }
105	
106	    async function refresh() {
107	      try {
108	        const res = await fetch('/api/jobs');
109	        if (!res.ok) return;
110	        const data = await res.json();
111	        jobList.replaceChildren(...data.jobs.map(buildItem));
112	      } catch {
113	        // Keep the last list on screen; the next poll will retry.
114	      }
115	    }
116	
117	    form.addEventListener('submit', async (event) => {
118	      event.preventDefault();
119	      showError('');
120	      submitBtn.disabled = true;
121	      try {
122	        const res = await fetch('/api/jobs', {
123	          method: 'POST',
124	          headers: { 'content-type': 'application/json' },
125	          body: JSON.stringify({
126	            input: inputEl.value,
127	            steps: fieldValue(stepsEl.value),
128	            failAttempts: fieldValue(failEl.value),
129	          }),
130	        });
131	        const data = await res.json().catch(() => undefined);
132	        if (res.status === 201 || res.status === 200) {
133	          inputEl.value = '';
134	          await refresh();
135	        } else {
136	          const err = data && data.error ? data.error : {};
137	          showError(err.message || `Request failed with status ${res.status}.`, err.fields);
138	        }
139	      } catch {
140	        showError('Could not reach the server. Try again.');
141	      } finally {
142	        submitBtn.disabled = false;
143	      }
144	    });
145	
146	    refresh();
147	    setInterval(refresh, 1000);
148	  </script>
149	</body>
150	</html>
